        Colors[20] := 'C0C0C0'; // Silver
        Colors[21] := '505050'; // Black

        R1 := 0.7;
        R2 := R1 * 0.95;

        N := 5;

        for i := 0 to N - 1 do begin
            ax[i] := cos(2*Pi/N * i);
            ay[i] := sin(2*Pi/N * i);
            x[2 * i] := R1 * cos(2*Pi/N * i);
            y[2 * i] := R1 * sin(2*Pi/N * i);
            x[2 * i + 1] := R2 * cos(2*Pi/N * (i+0.5));
            y[2 * i + 1] := R2 * sin(2*Pi/N * (i+0.5));
        end;

        D := R1 * 0.82;
        H := R1 * 2;
        HCut := R1 * 0.5;
